      '<span class="krv-title"></span>' +
      '<button type="button" class="krv-x" data-krvclose="1" aria-label="닫기" title="닫기">×</button></div>' +
      '<div class="krv-body"></div>' +
      '<div class="krv-foot"><button type="button" class="krv-cp">📋 본문 복사</button>' +
      '<span class="krv-src">개역개정 · 대한성서공회</span></div></div>';
